def apply_rule_smart(input_grid):
    output = []
    for r in range(3):
        row = []
        for c in range(6):
            vals = [input_grid[reg * 3 + r][c] for reg in (0,1,2,3)]
            if input_grid[r][c] != 0:  # region 0 has a value
                for v in vals:
                    if v != 0:
                        row.append(v)
                        break
            else:  # region 0 is empty, use last non-zero
                for v in reversed(vals):
                    if v != 0:
                        row.append(v)
                        break
                else:
                    row.append(0)
        output.append(row)
    return output

